def findKthNumber(n, k):
    def getSteps(n, n1, n2):
        steps = 0
        while n1 <= n:
            steps += min(n + 1, n2) - n1
            n1 *= 10
            n2 *= 10
        return steps

    current = 1
    k -= 1  # We start counting from 0

    while k > 0:
        steps = getSteps(n, current, current + 1)
        if steps <= k:
            current += 1
            k -= steps
        else:
            current *= 10
            k -= 1

    return current
